Why don't search terms like ( or $ match? String search terms are converted to regular expressions, so characters that are meaningful in a regular expression (like (, ., or $) aren't matched literally. Set the autoEscape prop to escape them: import Highlighter from "react-highlight-words";

function AutoEscapeExample() {
 return (
 <Highlighter
 autoEscape={true}
 searchWords={["$9.99", "(sale)"]}
 textToHighlight="Today only (sale): $9.99"
 />
 );
}
